import { forwardRef, type InputHTMLAttributes } from "react";

export const DatePicker = forwardRef<HTMLInputElement, Omit<InputHTMLAttributes<HTMLInputElement>, "type">>(({ className = "", ...props }, ref) => <input ref={ref} type="date" className={`co-h-10 co-rounded-md co-border co-border-black/20 co-bg-white co-px-3 co-text-sm co-outline-none focus-visible:co-ring-2 disabled:co-opacity-50 ${className}`.trim()} {...props} />);
DatePicker.displayName = "DatePicker";
